     8	import java.time.ZoneOffset;
     9	import java.util.Arrays;
    10	import java.util.List;
    11	import java.util.Optional;
    12	
    13	import org.springframework.jdbc.core.simple.JdbcClient;
    14	import org.springframework.stereotype.Repository;
    15	
    16	import com.loja.orders.checkout.CheckoutSummary;
    17	import com.loja.orders.common.Money;
    18	import com.loja.orders.coupon.PurchaseHistory;
    19	
    20	@Repository
    21	public class OrderRepository implements PurchaseHistory {
    22	
    23	    private final JdbcClient jdbc;
    24	
    25	    public OrderRepository(JdbcClient jdbc) {
    26	        this.jdbc = jdbc;
    27	    }
    28	
    29	    public void insert(Order order) {
    30	        CheckoutSummary s = order.summary();
    31	        jdbc.sql("""
    32	                INSERT INTO customer_order (id, cpf, email, status, created_at, tracking_code,
    33	                    products_subtotal, coupon_discount, shipping_cost, delivery_days, insurance,
    34	                    payment_adjustment, final_total, installments, installment_amount,
    35	                    next_purchase_credit, gift)
    36	                VALUES (:id, :cpf, :email, :status, :createdAt, NULL,
    37	                    :productsSubtotal, :couponDiscount, :shippingCost, :deliveryDays, :insurance,
    38	                    :paymentAdjustment, :finalTotal, :installments, :installmentAmount,
    39	                    :nextPurchaseCredit, :gift)
    40	                """)
    41	                .param("id", order.id())
    42	                .param("cpf", order.cpf())
